package com.droidmaker.core.project;

import com.droidmaker.core.json.Json;

import java.util.LinkedHashMap;
import java.util.Map;

/** A sound effect or music track. Either imported from a file or generated by the built-in synth. */
public class Sound extends Resource {
    public static final int KIND_EFFECT = 0, KIND_MUSIC = 1;

    /** Audio file relative to the project directory (wav/ogg/mp3), or null. */
    public String file;
    public int kind = KIND_EFFECT;
    public double volume = 1.0;
    /** Synth parameters when the sound was generated in-app (so it can be re-edited). */
    public Map<String, Object> synth;

    @Override public ResType type() { return ResType.SOUND; }

    @Override public Map<String, Object> toJson() {
        Map<String, Object> m = super.toJson();
        m.put("file", file);
        m.put("kind", (double) kind);
        m.put("volume", volume);
        if (synth != null) m.put("synth", synth);
        return m;
    }

    @Override public void fromJson(Map<String, Object> m) {
        super.fromJson(m);
        file = (String) m.get("file");
        kind = Json.integer(m, "kind", KIND_EFFECT);
        volume = Json.num(m, "volume", 1.0);
        synth = m.get("synth") instanceof Map ? new LinkedHashMap<>(Json.obj(m.get("synth"))) : null;
    }
}
